#overlapping kmers in order which make up the genome

def path_to_genome():
    args = path.split() #split returns a list of strings - kmers
    # start with first kmer, then append last character of each subsequent kmer, adding one new symbol to the genome at each new k-mer
    genome = args[0] + "".join(kmer[-1] for kmer in args[1:])
    return genome

print(path_to_genome())

